/**
 * Master GCC activity library (Level 3/4 WBS) generated from the Requirements Reference.
 * 16 WBS workstreams -> sub-workstreams -> activities, each with the recommended tracking fields.
 * The `workstream` field maps every WBS workstream onto one of the 7 dashboard workstreams.
 */
import type { Workstream, Status } from './common'

export interface WbsWorkstream { code: string; name: string; subs: { code: string; name: string; activities: { code: string; name: string }[] }[] }

export interface Activity {
  id: string
  code: string
  name: string
  wbsWorkstream: string
  subWorkstream: string
  workstream: Workstream
  responsible: string
  accountable: string
  vendor: string
  baselineStart: string
  baselineEnd: string
  forecastStart: string
  forecastEnd: string
  actualStart: string
  actualEnd: string
  status: Status
  percentComplete: number
  rag: 'Green' | 'Amber' | 'Red'
  daysDelayed: number
  predecessor: string
  successor: string
  criticalPath: boolean
  budgetLakh: number
  commitmentLakh: number
  actualLakh: number
  forecastLakh: number
  deliverable: string
  acceptanceCriteria: string
  evidence: string
  signOff: 'Signed' | 'Pending'
  lastUpdated: string
}

